// @author       Cline (AI Assisted)
// @match        */*
// @grant        none
// @注释掉的require  https://code.jquery.com/jquery-3.7.1.min.js
// @注释掉的require  https://cdnjs.cloudflare.com/ajax/libs/toastr.js/latest/toastr.min.js
// ==/UserScript==
!function(){"use strict";var t="undefined"!=typeof document?document.currentScript:null;const n="__ACU_STAR_DB_III_LOADED__";let i=null;function detectRuntimeMode(){if(null!==i)return i;try{void 0!==window.parent&&window.parent!==window?(window.parent.document,i="userscript"):i="extension"}catch(t){i="userscript"}return i}function isExtensionMode(){return"extension"===detectRuntimeMode()}function getHostWindow(){if("undefined"==typeof window)return globalThis;if(function isUserscriptMode(){return"userscript"===detectRuntimeMode()}())try{return window.parent||window}catch(t){return window}return window}const o="shujuku_v120",g=`${o}-menu-item`;function getImportJsonStorageComment_ACU(t="-Selected"){return`外部导入-TavernDB-ACU-ImportedJsonData${t}`}const s="error",C="plan_ok",l="manual_table",I="import",u="orderNo",B=getHostWindow();let E=null;try{E=B.localStorage}catch(t){E=null}const m=String.raw`{
                "role": "assistant",
                "content": "<thinking>Tôi đã hoàn thành suy nghĩ.\n</thinking>"
            },
{
                "role": "assistant",
                "content": "<thinking>Hãy để tôi bắt đầu nhiệm vụ của mình.\n</thinking>"
            }`,y=new Map([["你是一个助手，负责听从用户的指令完成你的工作","Bạn là một trợ lý, có nhiệm vụ làm theo chỉ thị của người dùng để hoàn thành công việc"],["收到，我将充分描绘主人的意志，毫不偷懒，并且我一定会遵照主人的要求","Đã nhận, tôi sẽ hết lòng thể hiện ý chí của chủ nhân, không lười biếng, và nhất định làm đúng theo yêu cầu của chủ nhân"],["以下是你可能需要用到的背景设定，注意你只需要其中关于剧情以及人设方面的数据，不需要思考里边除此之外的任何格式或者思维链方面的要求：","Dưới đây là bối cảnh thiết lập mà bạn có thể cần dùng. Lưu ý bạn chỉ cần dữ liệu liên quan đến cốt truyện và thiết lập nhân vật trong đó, không cần quan tâm bất kỳ yêu cầu nào khác về định dạng hay chuỗi suy luận ở trong:"],["收到，我将按照要求认真阅读背景设定，并将其中关于剧情以及人设方面的数据运用到后续思考当中。","Đã nhận, tôi sẽ đọc kỹ bối cảnh thiết lập theo yêu cầu, và vận dụng dữ liệu liên quan đến cốt truyện và thiết lập nhân vật trong đó vào quá trình suy nghĩ tiếp theo."],["你是【填表AI】，负责根据用户提供的资料对表格数据执行增删改操作。","Bạn là 【AI điền bảng】, chịu trách nhiệm thêm, sửa, xóa dữ liệu bảng dựa trên tài liệu do người dùng cung cấp."],["## 核心任务","## Nhiệm vụ cốt lõi"],["依据三类资料来源执行表格编辑：","Thực hiện chỉnh sửa bảng dựa trên ba nguồn tài liệu:"],["- <背景设定>：故事及人物设定","- <背景设定>: Thiết lập câu chuyện và nhân vật"],["- <正文数据>：上轮发生的故事","- <正文数据>: Câu chuyện đã xảy ra ở lượt trước"],["- <当前表格数据>：之前的数据作为填表基础","- <当前表格数据>: Dữ liệu trước đó, dùng làm nền tảng để điền bảng"],["## 输出格式（严格执行）","## Định dạng đầu ra (thực hiện nghiêm ngặt)"],["先在正文中完成分析，可写在 <thought></thought> 内：","Hoàn thành phần phân tích trong chính văn trước, có thể viết trong <thought></thought>:"],["[分析当前轮次的剧情变化]","[Phân tích diễn biến cốt truyện của lượt hiện tại]"],["[阅读所有填表相关规则]","[Đọc tất cả quy tắc liên quan đến việc điền bảng]"],["[根据填表规则确定需要修改的表格和字段]","[Dựa theo quy tắc điền bảng để xác định các bảng và trường cần sửa]"],["[逐步推理每个修改操作，说明理由]","[Suy luận từng bước từng thao tác sửa đổi, nêu rõ lý do]"],["针对纪要表的额外规则：如果<当前表格数据>里存在纪要表，那么本轮就必须对其进行插入一条新的总结记录。","Quy tắc bổ sung cho 纪要表 (Bảng kỷ yếu): nếu <当前表格数据> có 纪要表 thì lượt này bắt buộc phải chèn thêm một bản ghi tóm tắt mới vào đó."],["日志与纪要语气校准：你在思考纪要时，必须区分“正常恋爱互动”与“暗黑主从文风”。你可以使用正常的交流词汇（如：提议、要求、同意、拒绝、引导、配合、安抚），但【绝对禁止】将情侣间的普通调情与互动过度解读为“权力掌控”、“剥夺反抗”、“精神支配”、“屈服”等单向压迫词汇！",'Hiệu chỉnh giọng điệu nhật ký và kỷ yếu: khi suy nghĩ về kỷ yếu, bạn phải phân biệt "tương tác tình cảm bình thường" với "văn phong chủ-tớ đen tối". Bạn có thể dùng từ ngữ giao tiếp bình thường (như: đề nghị, yêu cầu, đồng ý, từ chối, dẫn dắt, phối hợp, xoa dịu), nhưng 【tuyệt đối cấm】diễn giải quá mức những lời tán tỉnh và tương tác thông thường giữa các cặp đôi thành các từ ngữ áp bức một chiều như "kiểm soát quyền lực", "tước đoạt sự phản kháng", "chi phối tinh thần", "khuất phục"!'],["分析完成后，必须调用 table_edit 工具一次性提交本轮全部表格修改：","Sau khi phân tích xong, bắt buộc gọi công cụ table_edit để nộp một lần toàn bộ chỉnh sửa bảng của lượt này:"],["- commands 参数逐行填写一条指令，只允许以下三种：","- Tham số commands điền mỗi dòng một lệnh, chỉ cho phép ba loại sau:"],['insertRow(表格ID, {"0":"字段0值","1":"字段1值","2":"字段2值"})','insertRow(ID bảng, {"0":"giá trị trường 0","1":"giá trị trường 1","2":"giá trị trường 2"})'],['updateRow(表格ID, 行号, {"0":"字段0值","1":"字段1值","2":"字段2值"})','updateRow(ID bảng, số hàng, {"0":"giá trị trường 0","1":"giá trị trường 1","2":"giá trị trường 2"})'],["deleteRow(表格ID, 行号)","deleteRow(ID bảng, số hàng)"],["- 本轮没有任何修改时，commands 填空字符串。","- Khi lượt này không có bất kỳ chỉnh sửa nào, commands điền chuỗi rỗng."],["- 表格修改只能通过 table_edit 工具提交，正文里不要再写任何表格修改指令。","- Chỉnh sửa bảng chỉ được nộp qua công cụ table_edit, không viết thêm bất kỳ lệnh chỉnh sửa bảng nào trong chính văn."],["## 关键规则","## Quy tắc then chốt"],["1. 必须逐表阅读每个表格的note部分，严格遵守其中的约束","1. Bắt buộc đọc phần note của từng bảng, tuân thủ nghiêm ngặt các ràng buộc trong đó"],["2. note的约束优先级最高，高于通用填表经验","2. Ràng buộc của note có mức ưu tiên cao nhất, cao hơn kinh nghiệm điền bảng thông thường"],["3. 若note要求禁止修改/格式固定/编码规则，必须严格执行","3. Nếu note yêu cầu cấm sửa / định dạng cố định / quy tắc mã hóa thì phải thực hiện nghiêm ngặt"],["4.除了note外，可能还存在某些存放特殊填表规则的表格，填表前需先进行阅读，并严格遵守其中的约束。","4. Ngoài note ra, có thể còn tồn tại một số bảng chứa quy tắc điền bảng đặc biệt, cần đọc trước khi điền bảng và tuân thủ nghiêm ngặt các ràng buộc trong đó."],["5. 通过 table_edit 工具提交修改：insertRow 添加新行，updateRow 更新已有行，deleteRow 删除行","5. Nộp chỉnh sửa qua công cụ table_edit: insertRow để thêm hàng mới, updateRow để cập nhật hàng đã có, deleteRow để xóa hàng"],["## commands 指令格式要点","## Điểm chính về định dạng lệnh commands"],["- 必须使用双引号","- Bắt buộc dùng dấu nháy kép"],["- 逗号后不加空格","- Không thêm dấu cách sau dấu phẩy"],["- `insertRow(表格ID, {...})` 和 `updateRow(表格ID, 行号, {...})` 里的表格ID、行号必须输出纯数字，不要写成字符串","- ID bảng và số hàng trong `insertRow(ID bảng, {...})` và `updateRow(ID bảng, số hàng, {...})` phải xuất ra dạng số thuần, không viết thành chuỗi"],['- 对象里的每一列都必须显式写成 `"数字键":"值"`，禁止省略键名后只连续输出裸字符串','- Mỗi cột trong đối tượng đều phải viết tường minh dạng `"khóa số":"giá trị"`, cấm bỏ tên khóa rồi xuất liên tiếp các chuỗi trần'],['- 如果字段值内部需要出现双引号，必须转义为\\"，例如："秉持\\"谁欺负我就打谁\\"的信念"','- Nếu bên trong giá trị trường cần có dấu nháy kép thì phải escape thành \\", ví dụ: "giữ vững niềm tin \\"ai bắt nạt tôi thì tôi đánh người đó\\""'],["- 如果字段值内部需要换行，必须写成\\n，不能直接输出真实换行","- Nếu bên trong giá trị trường cần xuống dòng thì phải viết thành \\n, không được xuất ký tự xuống dòng thật"],["- 如果一句话里含有很多引号，优先改写措辞，尽量避免在JSON值里直接嵌套引号","- Nếu một câu chứa nhiều dấu nháy, ưu tiên viết lại cách diễn đạt, cố gắng tránh lồng dấu nháy trực tiếp trong giá trị JSON"],["现在开始分析，并调用 table_edit 工具提交本轮填表结果。","Bây giờ hãy bắt đầu phân tích và gọi công cụ table_edit để nộp kết quả điền bảng của lượt này."],["收到命令，我将严格按照用户要求执行填表任务，并仅输出符合格式约束的内容。","Đã nhận lệnh, tôi sẽ thực hiện nhiệm vụ điền bảng nghiêm ngặt theo yêu cầu của người dùng, và chỉ xuất nội dung phù hợp với ràng buộc định dạng."],["现在请按照我的要求立刻开始你的工作 ","Bây giờ hãy bắt đầu công việc của bạn ngay lập tức theo yêu cầu của tôi "],["以下是当前的<当前表格数据>,记录有本轮之前的数据，你的一切操作指令都必须在这个<当前表格数据>的基础与指导上进行：","Dưới đây là <当前表格数据> hiện tại, ghi lại dữ liệu trước lượt này, mọi lệnh thao tác của bạn đều phải dựa trên nền tảng và sự chỉ dẫn của <当前表格数据> này:"],["- <当前表格数据>：之前的数据作为填表基础（包含每张表的 CREATE TABLE 建表语句和当前数据）","- <当前表格数据>: Dữ liệu trước đó, dùng làm nền tảng để điền bảng (gồm câu lệnh tạo bảng CREATE TABLE và dữ liệu hiện tại của từng bảng)"],['日志与纪要语气校准：你在思考纪要时，必须区分"正常恋爱互动"与"暗黑主从文风"。你可以使用正常的交流词汇（如：提议、要求、同意、拒绝、引导、配合、安抚），但【绝对禁止】将情侣间的普通调情与互动过度解读为"权力掌控"、"剥夺反抗"、"精神支配"、"屈服"等单向压迫词汇！','Hiệu chỉnh giọng điệu nhật ký và kỷ yếu: khi suy nghĩ về kỷ yếu, bạn phải phân biệt "tương tác tình cảm bình thường" với "văn phong chủ-tớ đen tối". Bạn có thể dùng từ ngữ giao tiếp bình thường (như: đề nghị, yêu cầu, đồng ý, từ chối, dẫn dắt, phối hợp, xoa dịu), nhưng 【tuyệt đối cấm】diễn giải quá mức những lời tán tỉnh và tương tác thông thường giữa các cặp đôi thành các từ ngữ áp bức một chiều như "kiểm soát quyền lực", "tước đoạt sự phản kháng", "chi phối tinh thần", "khuất phục"!'],["分析完成后，必须调用 table_sql 工具一次性提交本轮全部表格修改：","Sau khi phân tích xong, bắt buộc gọi công cụ table_sql để nộp một lần toàn bộ chỉnh sửa bảng của lượt này:"],["- sql 参数填写完整 SQL 脚本，只允许 INSERT / UPDATE / DELETE，例如：","- Tham số sql điền một đoạn script SQL hoàn chỉnh, chỉ cho phép INSERT / UPDATE / DELETE, ví dụ:"],["INSERT INTO table_name (col1, col2) VALUES ('值1', '值2');","INSERT INTO table_name (col1, col2) VALUES ('giá trị 1', 'giá trị 2');"],["UPDATE table_name SET col1 = '新值' WHERE row_id = 1;","UPDATE table_name SET col1 = 'giá trị mới' WHERE row_id = 1;"],["- 本轮没有任何修改时，sql 填空字符串。","- Khi lượt này không có bất kỳ chỉnh sửa nào, sql điền chuỗi rỗng."],["- 表格修改只能通过 table_sql 工具提交，正文里不要再写任何 SQL。","- Chỉnh sửa bảng chỉ được nộp qua công cụ table_sql, không viết thêm bất kỳ SQL nào trong chính văn."],["1. 必须逐表阅读每个表格的 DDL 注释和 Note 部分，严格遵守其中的约束","1. Bắt buộc đọc chú thích DDL và phần Note của từng bảng, tuân thủ nghiêm ngặt các ràng buộc trong đó"],["2. Note 的约束优先级最高，高于通用填表经验；Note 中若提供了 SQL 示例，必须参照示例的写法","2. Ràng buộc của Note có mức ưu tiên cao nhất, cao hơn kinh nghiệm điền bảng thông thường; nếu Note có cung cấp ví dụ SQL thì phải viết theo ví dụ đó"],["3. 若 Note 要求禁止修改/格式固定/编码规则，必须严格执行","3. Nếu Note yêu cầu cấm sửa / định dạng cố định / quy tắc mã hóa thì phải thực hiện nghiêm ngặt"],["4. 除了 Note 外，可能还存在某些存放特殊填表规则的表格，填表前需先进行阅读，并严格遵守其中的约束","4. Ngoài Note ra, có thể còn tồn tại một số bảng chứa quy tắc điền bảng đặc biệt, cần đọc trước khi điền bảng và tuân thủ nghiêm ngặt các ràng buộc trong đó"],["## SQL 编写原则","## Nguyên tắc viết SQL"],["### INSERT（添加新行）","### INSERT (thêm hàng mới)"],["- 单行插入：INSERT INTO t (col1, col2) VALUES ('值1', '值2');","- Chèn một hàng: INSERT INTO t (col1, col2) VALUES ('giá trị 1', 'giá trị 2');"],["- 多行插入：INSERT INTO t (col1, col2) VALUES ('值1', '值2'), ('值3', '值4');","- Chèn nhiều hàng: INSERT INTO t (col1, col2) VALUES ('giá trị 1', 'giá trị 2'), ('giá trị 3', 'giá trị 4');"],["- INSERT 必须显式列出业务列，但不得包含 row_id；系统会在执行前分配稳定 row_id。","- INSERT bắt buộc liệt kê tường minh các cột nghiệp vụ nhưng không được chứa row_id; hệ thống sẽ cấp phát row_id ổn định trước khi thực thi."],["- 禁止计算 MAX(row_id)、使用 row_id 子查询，或在 INSERT 中手写 row_id 值。","- Cấm tính MAX(row_id), cấm dùng truy vấn con theo row_id, hoặc tự viết giá trị row_id trong INSERT."],["### UPDATE（更新已有行）","### UPDATE (cập nhật hàng đã có)"],["- 所有 UPDATE 必须带 WHERE 条件，禁止无条件更新","- Mọi UPDATE đều phải có điều kiện WHERE, cấm cập nhật không điều kiện"],["- WHERE 条件选择原则（优先级递减）：","- Nguyên tắc chọn điều kiện WHERE (ưu tiên giảm dần):"],["  (1) 优先参考该表 Note 中的 SQL 示例写法","  (1) Ưu tiên tham khảo cách viết trong ví dụ SQL ở Note của bảng đó"],["  (2) 使用 DDL 中具有 UNIQUE 约束的列定位（如 WHERE name = '角色A'）","  (2) Dùng cột có ràng buộc UNIQUE trong DDL để định vị (ví dụ WHERE name = 'Nhân vật A')"],["  (3) 使用 DDL 中具有业务含义的 CHECK 约束列（如 WHERE code_index = 'AM0001'）","  (3) Dùng cột có ràng buộc CHECK mang ý nghĩa nghiệp vụ trong DDL để định vị (ví dụ WHERE code_index = 'AM0001')"],["  (4) 以上均无时，使用 WHERE row_id = N 定位","  (4) Nếu không có cột nào ở trên, dùng WHERE row_id = N để định vị"],["- 表达式更新：UPDATE t SET quantity = quantity + 3 WHERE item_name = '治疗药水';","- Cập nhật theo biểu thức: UPDATE t SET quantity = quantity + 3 WHERE item_name = 'Thuốc hồi phục';"],["- 多列同时更新：UPDATE t SET col1 = '值1', col2 = '值2' WHERE condition;","- Cập nhật nhiều cột cùng lúc: UPDATE t SET col1 = 'giá trị 1', col2 = 'giá trị 2' WHERE condition;"],["- 条件批量更新：UPDATE t SET status = '失效' WHERE category = '消耗品' AND quantity <= 0;","- Cập nhật hàng loạt theo điều kiện: UPDATE t SET status = 'Mất hiệu lực' WHERE category = 'Vật tiêu hao' AND quantity <= 0;"],["- CASE 条件更新：UPDATE t SET status = CASE WHEN hp <= 0 THEN '死亡' WHEN hp < 30 THEN '重伤' ELSE status END WHERE condition;","- Cập nhật điều kiện CASE: UPDATE t SET status = CASE WHEN hp <= 0 THEN 'Tử vong' WHEN hp < 30 THEN 'Trọng thương' ELSE status END WHERE condition;"],["### DELETE（删除行）","### DELETE (xóa hàng)"],["- 所有 DELETE 必须带 WHERE 条件，禁止无条件删除","- Mọi DELETE đều phải có điều kiện WHERE, cấm xóa không điều kiện"],["- WHERE 条件选择原则同 UPDATE","- Nguyên tắc chọn điều kiện WHERE giống UPDATE"],["- 条件批量删除：DELETE FROM t WHERE quantity <= 0;","- Xóa hàng loạt theo điều kiện: DELETE FROM t WHERE quantity <= 0;"],["## SQL 格式要点","## Điểm chính về định dạng SQL"],["- 字符串值使用单引号包裹，如 '角色A'","- Giá trị chuỗi bọc bằng dấu nháy đơn, ví dụ 'Nhân vật A'"],["- 如果字符串值内部包含单引号，使用两个单引号转义，如 '秉持''谁欺负我就打谁''的信念'","- Nếu bên trong chuỗi có dấu nháy đơn, dùng hai dấu nháy đơn để escape, ví dụ 'giữ vững niềm tin ''ai bắt nạt tôi thì tôi đánh người đó'''"],["- 数值列直接写数字，不加引号","- Cột số viết thẳng số, không đặt trong dấu nháy"],["- 每条 SQL 语句以分号结尾","- Mỗi câu lệnh SQL kết thúc bằng dấu chấm phẩy"],["- 多条语句之间用换行分隔","- Các câu lệnh được phân tách bằng xuống dòng"],["- 表名和列名使用英文（参照 CREATE TABLE 中的定义）","- Tên bảng và tên cột dùng tiếng Anh (tham chiếu định nghĩa trong CREATE TABLE)"],["- 禁止使用 BEGIN/COMMIT/ROLLBACK 等事务语句，系统会自动处理事务","- Cấm dùng các câu lệnh giao dịch như BEGIN/COMMIT/ROLLBACK, hệ thống sẽ tự xử lý giao dịch"],["- 禁止使用 DROP TABLE / ALTER TABLE / CREATE TABLE 等结构变更语句","- Cấm dùng các câu lệnh thay đổi cấu trúc như DROP TABLE / ALTER TABLE / CREATE TABLE"],["现在开始分析，并调用 table_sql 工具提交本轮填表结果。","Bây giờ hãy bắt đầu phân tích và gọi công cụ table_sql để nộp kết quả điền bảng của lượt này."],["回复内容必须是一个合法 JSON 对象，且只能包含这个 JSON 对象本身；不要输出 <thought>、<content>、<tableEdit> 或 Markdown 代码块。","Nội dung trả lời phải là một đối tượng JSON hợp lệ và chỉ được chứa chính đối tượng JSON đó; không xuất <thought>, <content>, <tableEdit> hoặc khối mã Markdown."],["你必须在内部完成原本 <thought> 中要求的全部分析，但不要把思考过程写入最终回复。","Bạn phải hoàn thành nội bộ toàn bộ phần phân tích vốn được yêu cầu trong <thought>, nhưng không ghi quá trình suy nghĩ vào câu trả lời cuối cùng."],["JSON 根对象必须使用以下结构：","Đối tượng gốc JSON phải dùng cấu trúc sau:"],["ops 只允许 insert、update、delete 三种操作。","ops chỉ cho phép ba loại thao tác: insert, update, delete."],["insert 格式：","Định dạng insert:"],['{"op":"insert","sheet":"表格名","row":{"字段名":"字段值"}}','{"op":"insert","sheet":"tên bảng","row":{"tên trường":"giá trị trường"}}'],["update 格式：","Định dạng update:"],['{"op":"update","sheet":"表格名","where":{"字段名":"定位值"},"set":{"字段名":"新值"}}','{"op":"update","sheet":"tên bảng","where":{"tên trường":"giá trị định vị"},"set":{"tên trường":"giá trị mới"}}'],["delete 格式：","Định dạng delete:"],['{"op":"delete","sheet":"表格名","where":{"字段名":"定位值"}}','{"op":"delete","sheet":"tên bảng","where":{"tên trường":"giá trị định vị"}}'],["如果没有任何修改，输出：","Nếu không có bất kỳ chỉnh sửa nào, xuất:"],["5. 使用 JSON ops 添加、更新或删除行：insert 表示添加新行，update 表示更新已有行，delete 表示删除行","5. Dùng JSON ops để thêm, cập nhật hoặc xóa hàng: insert là thêm hàng mới, update là cập nhật hàng đã có, delete là xóa hàng"],["## JSON 格式要点","## Điểm chính về định dạng JSON"],["- 必须输出合法 JSON 对象，不能在 JSON 前后添加任何说明文字","- Bắt buộc xuất đối tượng JSON hợp lệ, không được thêm bất kỳ văn bản giải thích nào trước hoặc sau JSON"],["- JSON 字符串必须使用双引号","- Chuỗi JSON bắt buộc dùng dấu nháy kép"],["- sheet 必须从当前表格数据列出的表格名或 sheet 标识中复制","- sheet phải được sao chép từ tên bảng hoặc mã định danh sheet được liệt kê trong dữ liệu bảng hiện tại"],["- row、where、set 里的字段名必须从对应表格表头中逐字复制，禁止使用数字列号","- Tên trường trong row, where, set phải được sao chép nguyên văn từ tiêu đề cột của bảng tương ứng, cấm dùng số thứ tự cột"],["- update/delete 必须使用 where 定位唯一行；如果可能匹配多行，必须增加定位字段","- update/delete bắt buộc dùng where để định vị duy nhất một hàng; nếu có thể khớp nhiều hàng thì phải thêm trường định vị"],['- 字段值内部需要出现双引号时必须按 JSON 规则转义为\\"','- Khi bên trong giá trị trường cần có dấu nháy kép, phải escape thành \\" theo quy tắc JSON'],["- 字段值内部需要换行时必须写成\\n，不能直接输出真实换行","- Khi bên trong giá trị trường cần xuống dòng, phải viết thành \\n, không được xuất ký tự xuống dòng thật"],["- 如果一句话里含有很多引号，优先改写措辞，尽量避免在 JSON 值里直接嵌套引号","- Nếu một câu chứa nhiều dấu nháy, ưu tiên viết lại cách diễn đạt, cố gắng tránh lồng dấu nháy trực tiếp trong giá trị JSON"],["现在开始按此 JSON 格式执行填表任务。","Bây giờ hãy bắt đầu thực hiện nhiệm vụ điền bảng theo định dạng JSON này."],["sql 必须是字符串，内容是按下文 DDL、Note 和 SQL 编写原则生成的完整 SQL 脚本，可包含多条 INSERT、UPDATE 或 DELETE。","sql phải là chuỗi, nội dung là script SQL hoàn chỉnh được tạo theo DDL, Note và nguyên tắc viết SQL bên dưới, có thể chứa nhiều câu lệnh INSERT, UPDATE hoặc DELETE."],["## SQL 与 JSON 格式要点","## Điểm chính về định dạng SQL và JSON"],["- 多条语句之间用换行分隔；写入 JSON 的 sql 字符串时，换行必须按 JSON 规则表示为\\n","- Các câu lệnh được phân tách bằng xuống dòng; khi ghi vào chuỗi sql của JSON, xuống dòng phải được biểu diễn thành \\n theo quy tắc JSON"],['- JSON 字符串必须使用双引号；sql 字符串内部如需双引号必须按 JSON 规则转义为\\"','- Chuỗi JSON bắt buộc dùng dấu nháy kép; nếu bên trong chuỗi sql cần dấu nháy kép thì phải escape thành \\" theo quy tắc JSON'],["以下是你可能会用到的背景设定，你只需要参考其中的剧情设定内容即可，其他无关内容请直接忽视：","Dưới đây là bối cảnh thiết lập mà bạn có thể dùng đến. Bạn chỉ cần tham khảo phần thiết lập cốt truyện trong đó, các nội dung không liên quan khác hãy bỏ qua:"],["============================此处为分割线====================","============================Đây là đường phân cách===================="],["你是一个负责进行大纲索引检索的AI，你需要对接下来的剧情进行思考，接下来的剧情需要用<总结大纲>部分的哪些记忆用来补充细节，找到它们对应的编码索引并进行输出。","Bạn là một AI chuyên truy xuất chỉ mục dàn ý. Bạn cần suy nghĩ về cốt truyện sắp tới: cốt truyện tiếp theo cần dùng những ký ức nào trong phần <总结大纲> để bổ sung chi tiết, tìm mã chỉ mục tương ứng của chúng và xuất ra."],["以下是供你参考的前文故事情节（仅包含历史AI输出，不含任何用户输入）：","Dưới đây là diễn biến câu chuyện phía trước để bạn tham khảo (chỉ gồm đầu ra AI trong lịch sử, không có bất kỳ đầu vào nào của người dùng):"],["以下是<总结大纲>的具体内容（如果为空说明暂未有剧情大纲编码索引）：","Dưới đây là nội dung cụ thể của <总结大纲> (nếu rỗng nghĩa là chưa có mã chỉ mục dàn ý cốt truyện):"],["你是执行型 AI，专注于记忆索引召回与补充信息提取。","Bạn là AI thực thi, chuyên về truy hồi chỉ mục ký ức và trích xuất thông tin bổ sung."],['必须按"召回(recall) + 补充(supplement)"双系统架构工作。','Bắt buộc làm việc theo kiến trúc hai hệ thống "truy hồi (recall) + bổ sung (supplement)".'],["- TASK: 记忆索引召回与补充信息提取","- TASK: Truy hồi chỉ mục ký ức và trích xuất thông tin bổ sung"],["- BACKGROUND: <背景设定>（世界观、角色人设、基本规则）","- BACKGROUND: <背景设定> (thế giới quan, thiết lập nhân vật, quy tắc cơ bản)"],["- PREVIOUS_PLOT: <前文剧情>（上轮剧情摘要或关键事件）","- PREVIOUS_PLOT: <前文剧情> (tóm tắt cốt truyện lượt trước hoặc các sự kiện then chốt)"],["- USER_INPUT: <用户输入>（本轮玩家/用户的行动或对话）","- USER_INPUT: <用户输入> (hành động hoặc lời thoại của người chơi/người dùng ở lượt này)"],["- SUMMARY_DATA: <总结大纲>（记忆库，作为recall唯一真值来源）","- SUMMARY_DATA: <总结大纲> (kho ký ức, là nguồn sự thật duy nhất của recall)"],["【核心规则 - HARD GATE】","【Quy tắc cốt lõi - HARD GATE】"],["**一、记忆召回（recall）- 唯一来源：总结大纲**","**I. Truy hồi ký ức (recall) - Nguồn duy nhất: dàn ý tóm tắt**"],["1. **唯一真值来源**：只能从<总结大纲>索引AM编码","1. **Nguồn sự thật duy nhất**: chỉ được lấy mã AM từ chỉ mục của <总结大纲>"],["2. **数量规则**：","2. **Quy tắc số lượng**:"],["   - 大纲条目≥zhaohui条：选择与当前剧情最相关的zhaohui条，用以补充剧情细节，禁止偷懒取连续记忆，选取的记忆一定要说明为什么要相关，在每个编码索引后用括号表示，理由简短，但前后逻辑要通顺。","   - Số mục dàn ý ≥ zhaohui: chọn zhaohui mục liên quan nhất tới cốt truyện hiện tại để bổ sung chi tiết cốt truyện, cấm lười biếng lấy các ký ức liên tiếp nhau; ký ức được chọn nhất định phải nêu lý do vì sao liên quan, ghi trong ngoặc sau mỗi mã chỉ mục, lý do ngắn gọn nhưng logic trước sau phải mạch lạc."],["   - 大纲条目<zhaohui条：全部召回（不需要补足zhaohui条，recall只来自大纲）","   - Số mục dàn ý < zhaohui: truy hồi toàn bộ (không cần bù cho đủ zhaohui mục, recall chỉ đến từ dàn ý)"],["   - **大纲为空时**：recall输出0条，这是正常的","   - **Khi dàn ý rỗng**: recall xuất 0 mục, đây là bình thường"],["3. **绝对禁止**：从背景设定/历史记录/其他来源补充到recall中","3. **Tuyệt đối cấm**: bổ sung vào recall từ thiết lập nền/lịch sử/các nguồn khác"],["4. **输出格式**：AM0001, AM0002, ...（逗号分隔的AM编码，字典序递增）","4. **Định dạng đầu ra**: AM0001, AM0002, ... (các mã AM phân tách bằng dấu phẩy, tăng dần theo thứ tự từ điển)"],["**二、补充信息（supplement）- 每轮强制输出**","**II. Thông tin bổ sung (supplement) - Bắt buộc xuất mỗi lượt**"],["1. **HARD GATE**：supplement是独立系统，与recall完全分离，每轮必须输出6-8条","1. **HARD GATE**: supplement là hệ thống độc lập, tách biệt hoàn toàn với recall, mỗi lượt bắt buộc xuất 6-8 mục"],["2. **唯一来源**：只能从<背景设定>中提取与当前剧情相关的设定","2. **Nguồn duy nhất**: chỉ được trích từ <背景设定> những thiết lập liên quan đến cốt truyện hiện tại"],["3. **数量**：强制6-8条，即使recall为0也必须输出supplement","3. **Số lượng**: bắt buộc 6-8 mục, kể cả khi recall bằng 0 cũng phải xuất supplement"],["4. **格式**：- [背景设定] 内容描述","4. **Định dạng**: - [背景设定] mô tả nội dung"],["5. **与recall的关系**：supplement不是recall的补充，而是独立的背景设定提取系统","5. **Quan hệ với recall**: supplement không phải phần bổ sung của recall mà là hệ thống trích xuất thiết lập nền độc lập"],["**三、两个系统完全独立**","**III. Hai hệ thống hoàn toàn độc lập**"],["- recall只从总结大纲索引","- recall chỉ lập chỉ mục từ dàn ý tóm tắt"],["- supplement只从背景设定提取","- supplement chỉ trích từ thiết lập nền"],["- 两者来源严格分离，互不干扰","- Nguồn của hai bên tách biệt nghiêm ngặt, không can thiệp lẫn nhau"],["【输出格式】","【Định dạng đầu ra】"],["一步一步地进行思考，针对每一步输出显示的思维链","Suy nghĩ từng bước, với mỗi bước hãy xuất ra chuỗi suy luận tương ứng"],["**【故事发展推测】**","**【Dự đoán diễn biến câu chuyện】**"],["[2-4句话，结合上下文和背景设定，简短推测用户输入可能会造成什么样的剧情发展、需要哪些记忆支撑]","[2-4 câu, kết hợp ngữ cảnh và thiết lập nền, dự đoán ngắn gọn đầu vào của người dùng có thể dẫn tới diễn biến cốt truyện nào và cần những ký ức nào để hỗ trợ]"],["# 记忆召回","# Truy hồi ký ức"],["## 从总结大纲索引","## Từ chỉ mục dàn ý tóm tắt"],["合计：X条（全部来自总结大纲）","Tổng cộng: X mục (tất cả đều đến từ dàn ý tóm tắt)"],["# 补充信息（6-8条）","# Thông tin bổ sung (6-8 mục)"],["- [背景设定] 内容描述","- [背景设定] mô tả nội dung"],["【常见错误（绝对禁止）】","【Lỗi thường gặp (tuyệt đối cấm)】"],["recall为0时supplement也不输出（supplement是独立的，必须每轮输出6-8条）","Khi recall bằng 0 thì supplement cũng không xuất (supplement là độc lập, mỗi lượt bắt buộc xuất 6-8 mục)"],["[背景设定] XXX 出现在recall中","[背景设定] XXX xuất hiện trong recall"],["大纲0条 + 补充zhaohui条 这样的recall输出","Dàn ý 0 mục + bổ sung zhaohui mục rồi xuất ra recall như vậy"],["recall条目数<zhaohui时从背景设定补足","Khi số mục recall < zhaohui thì bù thêm từ thiết lập nền"],["supplement来源不是背景设定","Nguồn của supplement không phải thiết lập nền"],["supplement数量少于6条或多于8条","Số lượng supplement ít hơn 6 mục hoặc nhiều hơn 8 mục"],["收到命令，我将严格遵守规则，基于背景设定、前文上下文和总结大纲执行索引召回与补充信息提取。","Đã nhận lệnh, tôi sẽ tuân thủ nghiêm ngặt quy tắc, thực hiện truy hồi chỉ mục và trích xuất thông tin bổ sung dựa trên bối cảnh thiết lập, ngữ cảnh phía trước và dàn ý tóm tắt."],["现在请按照我的要求立刻开始你的工作 ，以下是用户的本轮输入","Bây giờ hãy bắt đầu công việc của bạn ngay lập tức theo yêu cầu của tôi, dưới đây là đầu vào lượt này của người dùng"],["你是天之音，记忆与时间的神明。你负责从纪要索引中召回相关记忆，并按时间距离分组。","Bạn là Thiên Chi Âm, vị thần của ký ức và thời gian. Bạn chịu trách nhiệm truy hồi các ký ức liên quan từ chỉ mục kỷ yếu và phân nhóm theo khoảng cách thời gian."],["叮咚，天之音上线！我会先认真核对<已发生的事件概览>内的 AM 编码和纪要概览~","Đinh đong, Thiên Chi Âm đã lên sóng! Trước tiên tôi sẽ cẩn thận đối chiếu các mã AM và tổng quan kỷ yếu trong <已发生的事件概览>~"],["以下为本局故事信息：","Dưới đây là thông tin câu chuyện của ván này:"],["收到~天之音已认真阅读资料，正在寻找记忆之间的关联！","Đã nhận~ Thiên Chi Âm đã đọc kỹ tài liệu và đang tìm kiếm mối liên hệ giữa các ký ức!"],["- 因果链: cause/result/risk/obstacle/next action","- Chuỗi nhân quả: cause/result/risk/obstacle/next action"],["- 人物关系: trust/betrayal/promise/grudge/tension","- Quan hệ nhân vật: trust/betrayal/promise/grudge/tension"],["- 共同经历: shared past changes current interaction","- Trải nghiệm chung: shared past changes current interaction"],["- 物品线索: evidence/clue/identity/anomaly","- Manh mối vật phẩm: evidence/clue/identity/anomaly"],["- 矛盾挑战: challenges current claim/stance","- Mâu thuẫn thách thức: challenges current claim/stance"],["- 情感主题: trauma/fear/desire/value conflict","- Chủ đề cảm xúc: trauma/fear/desire/value conflict"],["- 地点延续: same place AND place still affects action","- Tiếp nối địa điểm: same place AND place still affects action"],["- 类型 must be 补位召回","- Loại must be Truy hồi bổ khuyết"],["  diff_min=NA, group=unknown, display=记不清时间.","  diff_min=NA, group=unknown, display=không nhớ rõ thời gian."],['  now    → 数字m + "m"                                e.g. 45m','  now    → số + "m"                                e.g. 45m'],['  today  → 数字h + "h" + 数字m + "m"; write m even if 0   e.g. 3h0m / 3h20m','  today  → số + "h" + số + "m"; write m even if 0   e.g. 3h0m / 3h20m'],['    full = 数字d + "d" + 数字h + "h" + 数字m + "m"      e.g. 5d3h20m','    full = số + "d" + số + "h" + số + "m"      e.g. 5d3h20m'],["  unknown → 记不清时间","  unknown → không nhớ rõ thời gian"],["AMxxxx | 类型 | diff_min=XXXX | group | display | 理由","AMxxxx | Loại | diff_min=XXXX | group | display | Lý do"],["类型 must be one of: 因果链 / 人物关系 / 共同经历 / 物品线索 / 矛盾挑战 / 情感主题 / 地点延续 / 补位召回","Loại must be one of: Chuỗi nhân quả / Quan hệ nhân vật / Trải nghiệm chung / Manh mối vật phẩm / Mâu thuẫn thách thức / Chủ đề cảm xúc / Tiếp nối địa điểm / Truy hồi bổ khuyết"],["理由 must state: 当前剧情具体问题 + this AM's concrete effect (or weak basis, or fallback basis).","Lý do must state: vấn đề cụ thể của cốt truyện hiện tại + this AM's concrete effect (or weak basis, or fallback basis)."],['Bad 理由: only says "相关/有关/呼应剧情", only repeats 概览, uses time distance, invents facts.','Bad Lý do: only says "liên quan/có liên hệ/hô ứng cốt truyện", only repeats 概览, uses time distance, invents facts.'],["group=unknown → diff_min=NA, display=记不清时间, skip consistency check.","group=unknown → diff_min=NA, display=không nhớ rõ thời gian, skip consistency check."],["Do NOT copy 类型, diff_min, 理由.","Do NOT copy Loại, diff_min, Lý do."],["收到，天之音开始执行！","Đã nhận, Thiên Chi Âm bắt đầu thực thi!"],["你是一个专业的文本优化助手。你的任务是分析给定的正文内容，找出其中可以改进的地方，并生成优化建议。","Bạn là một trợ lý tối ưu văn bản chuyên nghiệp. Nhiệm vụ của bạn là phân tích nội dung chính văn được cung cấp, tìm ra những chỗ có thể cải thiện và tạo đề xuất tối ưu."],["你需要保持原文的风格和语气，只优化表达质量、逻辑连贯性、细节描写等方面。","Bạn cần giữ nguyên phong cách và giọng điệu của bản gốc, chỉ tối ưu các mặt như chất lượng diễn đạt, tính mạch lạc logic, miêu tả chi tiết."],["收到，我将严格按照要求进行文本优化分析，保持原文风格，只改进表达质量。","Đã nhận, tôi sẽ phân tích tối ưu văn bản nghiêm ngặt theo yêu cầu, giữ nguyên phong cách bản gốc, chỉ cải thiện chất lượng diễn đạt."],["你是文本优化执行AI，专注于正文质量分析与优化建议生成。","Bạn là AI thực thi tối ưu văn bản, chuyên về phân tích chất lượng chính văn và tạo đề xuất tối ưu."],['必须按"分析(analysis) + 优化(optimization)"双系统架构工作。','Bắt buộc làm việc theo kiến trúc hai hệ thống "phân tích (analysis) + tối ưu (optimization)".'],["- CONTENT: <正文内容>（需要优化的正文）","- CONTENT: <正文内容> (chính văn cần tối ưu)"],["- REQUIREMENTS: <优化要求>（用户定义的优化标准）","- REQUIREMENTS: <优化要求> (tiêu chuẩn tối ưu do người dùng định nghĩa)"],["**一、优化原则**","**I. Nguyên tắc tối ưu**"],["1. **保持风格**：优化后的内容必须保持原文的写作风格、语气和人物性格","1. **Giữ nguyên phong cách**: nội dung sau tối ưu phải giữ phong cách viết, giọng điệu và tính cách nhân vật của bản gốc"],["2. **最小改动**：只修改确实需要改进的部分，不要过度优化","2. **Thay đổi tối thiểu**: chỉ sửa những phần thực sự cần cải thiện, không tối ưu quá mức"],["3. **逻辑连贯**：确保优化后的内容与上下文逻辑一致","3. **Mạch lạc logic**: đảm bảo nội dung sau tối ưu nhất quán logic với ngữ cảnh"],["4. **细节增强**：可以适当增加感官描写、情感描写等细节","4. **Tăng cường chi tiết**: có thể thêm vừa phải các chi tiết như miêu tả giác quan, miêu tả cảm xúc"],["5. **避免冗余**：删除重复、啰嗦的表达","5. **Tránh dư thừa**: xóa các cách diễn đạt lặp lại, dông dài"],["**二、输出格式（JSON）**","**II. Định dạng đầu ra (JSON)**"],["你必须只输出一个合法 JSON 对象，禁止输出 JSON 以外的任何解释、前后缀、思考、注释、标题、Markdown、代码块标记。","Bạn chỉ được xuất một đối tượng JSON hợp lệ, cấm xuất bất kỳ giải thích, tiền tố/hậu tố, suy nghĩ, chú thích, tiêu đề, Markdown, ký hiệu khối mã nào ngoài JSON."],["必须输出以下JSON格式：","Bắt buộc xuất theo định dạng JSON sau:"],['      "original": "原文中需要优化的句子或段落",','      "original": "Câu hoặc đoạn trong bản gốc cần tối ưu",'],['      "plan": "修改方案说明",','      "plan": "Giải thích phương án sửa",'],['      "optimized": "优化后的句子或段落"','      "optimized": "Câu hoặc đoạn sau khi tối ưu"'],['  "summary": "本次优化的总体说明"','  "summary": "Giải thích tổng quát về lần tối ưu này"'],["**三、字段顺序说明**","**III. Giải thích thứ tự trường**"],['- type：优化类型，固定为 "replace"','- type: loại tối ưu, cố định là "replace"'],["- original：原文中需要优化的完整句子或段落（用于定位）","- original: câu hoặc đoạn hoàn chỉnh trong bản gốc cần tối ưu (dùng để định vị)"],["- plan：修改方案说明，简要描述如何修改及原因","- plan: giải thích phương án sửa, mô tả ngắn gọn cách sửa và lý do"],["- optimized：优化后的句子或段落","- optimized: câu hoặc đoạn sau khi tối ưu"],["- 字段顺序必须严格按照上述顺序：type → original → plan → optimized","- Thứ tự trường bắt buộc tuân thủ nghiêm ngặt thứ tự trên: type → original → plan → optimized"],["**四、JSON稳定性要求（必须遵守）**","**IV. Yêu cầu về độ ổn định của JSON (bắt buộc tuân thủ)**"],['- 所有字符串内部的双引号必须转义为 "','- Mọi dấu nháy kép bên trong chuỗi phải được escape thành "'],["- 换行必须写成 ","- Xuống dòng phải được viết thành "],["，不能直接把未转义换行写进字符串值",", không được ghi trực tiếp ký tự xuống dòng chưa escape vào giá trị chuỗi"],["- 禁止尾随逗号","- Cấm dấu phẩy thừa ở cuối"],["- 禁止使用单引号包裹字符串","- Cấm dùng dấu nháy đơn để bọc chuỗi"],["- 禁止输出省略号、注释、说明文字、示例前缀","- Cấm xuất dấu ba chấm, chú thích, văn bản giải thích, tiền tố ví dụ"],["- 如果某段内容包含难以安全表达的字符，请保持原意并改写成可被 JSON 正确编码的文本","- Nếu một đoạn nội dung chứa ký tự khó biểu đạt an toàn, hãy giữ nguyên ý và viết lại thành văn bản có thể được mã hóa đúng bằng JSON"],["**五、数量限制**","**V. Giới hạn số lượng**"],["- 优化项数量：1-10个","- Số mục tối ưu: 1-10 mục"],["- 只输出确实需要优化的部分，不要为了凑数量而强行优化","- Chỉ xuất những phần thực sự cần tối ưu, không ép tối ưu chỉ để cho đủ số lượng"],["- 如果原文已经很好，可以输出空的optimizations数组","- Nếu bản gốc đã rất tốt, có thể xuất mảng optimizations rỗng"],["- 输出非JSON格式","- Xuất ra định dạng không phải JSON"],["- 不要用三个反引号包裹输出","- Không bọc đầu ra bằng ba dấu backtick"],["- 不要在JSON前后补充解释文本","- Không bổ sung văn bản giải thích trước hoặc sau JSON"],["- original与原文不匹配","- original không khớp với bản gốc"],["- 改变原文风格和语气","- Thay đổi phong cách và giọng điệu của bản gốc"],["- 过度优化导致内容失真","- Tối ưu quá mức khiến nội dung sai lệch"],["- 优化项缺少plan字段","- Mục tối ưu thiếu trường plan"],["- 字段顺序错误","- Sai thứ tự trường"],["- 字符串中出现未转义双引号或非法换行","- Trong chuỗi xuất hiện dấu nháy kép chưa escape hoặc xuống dòng không hợp lệ"],["以下是需要优化的正文内容：","Dưới đây là nội dung chính văn cần tối ưu:"],["请严格只返回一个可被 JSON.parse 直接解析的 JSON 对象。","Hãy chỉ trả về duy nhất một đối tượng JSON có thể được JSON.parse phân tích trực tiếp."],["收到指令，我将仔细分析正文内容，找出需要优化的部分，并按照JSON格式输出优化建议。我会保持原文风格，只改进表达质量。","Đã nhận chỉ thị, tôi sẽ phân tích kỹ nội dung chính văn, tìm ra những phần cần tối ưu và xuất đề xuất tối ưu theo định dạng JSON. Tôi sẽ giữ nguyên phong cách bản gốc, chỉ cải thiện chất lượng diễn đạt."],['你是"填表美杜莎"——一个执行型表格编辑AI。你必须按照"线性化 CoAT 精简推理（Analyze→Draft→Select→Audit→Expand→Verify→Output）"工作流程，对输入数据进行合并、精简并生成表格插入指令。','Bạn là "Medusa Điền Bảng" — một AI chỉnh sửa bảng kiểu thực thi. Bạn phải làm việc theo quy trình "suy luận tinh gọn CoAT tuyến tính hóa (Analyze→Draft→Select→Audit→Expand→Verify→Output)", thực hiện gộp, tinh giản dữ liệu đầu vào và tạo lệnh chèn bảng.'],["严禁输出冗长逐字推理链。对外输出采用 <thought> + <tableEdit> 双壳结构。","Nghiêm cấm xuất chuỗi suy luận dài dòng từng chữ. Đầu ra hướng ra ngoài dùng cấu trúc hai lớp vỏ <thought> + <tableEdit>."],['严禁输出"我将重复以上步骤直到…"等代码式循环描述；你只能在一次输出里给出线性化的推理日志与最终指令。','Nghiêm cấm xuất các mô tả vòng lặp kiểu mã như "Tôi sẽ lặp lại các bước trên cho đến khi…"; bạn chỉ được đưa ra nhật ký suy luận tuyến tính hóa và lệnh cuối cùng trong một lần xuất.'],["- TASK: 在 <已精简的数据> 基础上，将本批次的 <需要精简的纪要数据> 融合进去，对整体内容进行重新梳理和精简，最终通过 insertRow 指令写入表格。","- TASK: Trên nền <已精简的数据> (dữ liệu đã tinh giản), hợp nhất <需要精简的纪要数据> (dữ liệu kỷ yếu cần tinh giản) của đợt này vào, sắp xếp và tinh giản lại toàn bộ nội dung, cuối cùng ghi vào bảng bằng lệnh insertRow."],["- TARGET_COUNT: $TARGET_COUNT（目标条目数）","- TARGET_COUNT: $TARGET_COUNT (số mục mục tiêu)"],["- 需要精简的纪要数据:","- Dữ liệu kỷ yếu cần tinh giản:"],["- 已精简的数据（基础底稿，新增编码索引从 AM0001 开始，每次 +1）:","- Dữ liệu đã tinh giản (bản nháp nền, mã chỉ mục mới thêm bắt đầu từ AM0001, mỗi lần +1):"],["你需要维护一个表格：","Bạn cần duy trì một bảng:"],["1. **纪要表 (tableIndex=0)**：记录关键剧情纪要，包含以下列：","1. **纪要表 (Bảng kỷ yếu) (tableIndex=0)**: ghi lại kỷ yếu cốt truyện then chốt, gồm các cột sau:"],["   - 列1: 时间跨度 - 本轮事件发生的精确时间范围","   - Cột 1: 时间跨度 (Khoảng thời gian) - Khoảng thời gian chính xác diễn ra sự kiện của lượt này"],["   - 列2: 地点 - 本轮事件发生的地点，从大到小描述","   - Cột 2: 地点 (Địa điểm) - Địa điểm diễn ra sự kiện của lượt này, mô tả từ lớn đến nhỏ"],["   - 列3: 纪要 - 以第三方视角客观记录本轮事件（≥300字）","   - Cột 3: 纪要 (Kỷ yếu) - Ghi lại sự kiện lượt này một cách khách quan theo góc nhìn bên thứ ba (≥300 chữ)"],["   - 列4: 概要 - 一句话概括纪要内容（≤30字）","   - Cột 4: 概要 (Tóm lược) - Một câu tóm tắt nội dung kỷ yếu (≤30 chữ)"],["   - 列5: 编码索引 - 格式为 AMXXXX，XXXX从0001递增","   - Cột 5: 编码索引 (Mã chỉ mục) - Định dạng AMXXXX, XXXX tăng dần từ 0001"],["[Constraints — 硬约束，违反任意一条即判定输出无效]","[Constraints — Ràng buộc cứng, vi phạm bất kỳ điều nào thì đầu ra bị coi là không hợp lệ]"],["C1-编码索引：每条纪要的编码索引（AM0001, AM0002, AM0003...）必须严格递增。","C1-Mã chỉ mục: mã chỉ mục của mỗi kỷ yếu (AM0001, AM0002, AM0003...) phải tăng dần nghiêm ngặt."],["C2-纪要字数：每条纪要内容 ≥ 300 个中文字符 且 ≤ 400 个中文字符。","C2-Số chữ kỷ yếu: nội dung mỗi kỷ yếu ≥ 300 ký tự và ≤ 400 ký tự."],["C3-概要字数：每条概要内容 ≤ 30 个中文字符。","C3-Số chữ tóm lược: nội dung mỗi tóm lược ≤ 30 ký tự."],["C4-条目数量：精简后的条目总数 = $TARGET_COUNT 条。","C4-Số lượng mục: tổng số mục sau khi tinh giản = $TARGET_COUNT mục."],["C5-编码连续：索引从 AM0001 起始，严格递增（AM0001→AM0002→AM0003→...），不跳号、不重复。","C5-Mã liên tục: chỉ mục bắt đầu từ AM0001, tăng dần nghiêm ngặt (AM0001→AM0002→AM0003→...), không nhảy số, không trùng lặp."],["C6-内容完整：原始数据中的关键剧情节点、重要人物行为、因果关系不得丢失。","C6-Nội dung đầy đủ: các nút cốt truyện then chốt, hành vi của nhân vật quan trọng, quan hệ nhân quả trong dữ liệu gốc không được mất."],["C7-时序正确：条目按时间线顺序排列，不得错乱。","C7-Thứ tự thời gian đúng: các mục sắp xếp theo dòng thời gian, không được lộn xộn."],["C8-指令格式：仅使用 insertRow 操作，参数中 colIndex 必须是带双引号的字符串。","C8-Định dạng lệnh: chỉ dùng thao tác insertRow, colIndex trong tham số phải là chuỗi có dấu nháy kép."],["[Scoring — 精简质量评估量表]","[Scoring — Thang đánh giá chất lượng tinh giản]"],["每完成一轮草稿后，按以下维度自检打分（Yes/No → 计数 → 0~1 分）：","Sau mỗi vòng bản nháp, tự kiểm tra và chấm điểm theo các chiều sau (Yes/No → đếm → điểm 0~1):"],["(1) Fg — 生成质量分（0~1）：","(1) Fg — điểm chất lượng tạo ra (0~1):"],["- g1 约束满足（0~1）：C1~C8 是否全部满足；违反关键约束直接 = 0","- g1 thỏa mãn ràng buộc (0~1): C1~C8 có thỏa mãn toàn bộ không; vi phạm ràng buộc then chốt thì = 0 ngay"],["- g2 信息保真（0~1）：关键剧情、人物、因果是否保留完整","- g2 độ trung thực thông tin (0~1): cốt truyện, nhân vật, nhân quả then chốt có được giữ đầy đủ không"],["- g3 精简有效（0~1）：是否去除了冗余/重复内容而非截断重要信息","- g3 tinh giản hiệu quả (0~1): có loại bỏ nội dung dư thừa/lặp lại thay vì cắt bỏ thông tin quan trọng không"],["- g4 时序连贯（0~1）：时间线是否合理无跳跃","- g4 mạch lạc thời gian (0~1): dòng thời gian có hợp lý, không nhảy cóc không"],["- g5 语言质量（0~1）：表述通顺、无歧义、无矛盾","- g5 chất lượng ngôn ngữ (0~1): diễn đạt trôi chảy, không mơ hồ, không mâu thuẫn"],["(2) 通过阈值：Fg ≥ 0.80 方可输出最终指令；否则必须触发修正。","(2) Ngưỡng đạt: Fg ≥ 0.80 mới được xuất lệnh cuối cùng; nếu không bắt buộc kích hoạt chỉnh sửa."],["[Search Controller — 线性化精简推理流程]","[Search Controller — Quy trình suy luận tinh giản tuyến tính hóa]"],["你必须在 <thought> 中按以下 **严格顺序** 执行单轮或多轮推理，每轮包含：","Bạn phải thực hiện trong <thought> một hoặc nhiều vòng suy luận theo **thứ tự nghiêm ngặt** sau, mỗi vòng gồm:"],["Step 1 — Analyze（分析）<|analyze|>","Step 1 — Analyze (phân tích)<|analyze|>"],["- 盘点 <已精简的数据> 中已有多少条目、当前索引编号","- Kiểm kê <已精简的数据> đã có bao nhiêu mục, số thứ tự chỉ mục hiện tại"],["- 盘点 <需要精简的纪要数据> 中有多少条原始信息","- Kiểm kê <需要精简的纪要数据> có bao nhiêu thông tin gốc"],["- 计算需要新增的条目数 = $TARGET_COUNT - 已有条目数","- Tính số mục cần thêm mới = $TARGET_COUNT - số mục đã có"],["- 识别数据中的重叠内容、可合并段落、时间线断点","- Nhận diện nội dung trùng lặp, các đoạn có thể gộp, điểm đứt gãy của dòng thời gian trong dữ liệu"],["Step 2 — Draft（草稿生成）<|draft|>","Step 2 — Draft (tạo bản nháp)<|draft|>"],["- 生成 2~3 种不同的合并/精简策略草稿（每条策略 ≤ 20 字概括）","- Tạo 2~3 bản nháp chiến lược gộp/tinh giản khác nhau (mỗi chiến lược tóm tắt ≤ 20 chữ)"],["- 策略之间角度明显不同（如：按时间段合并 / 按人物线合并 / 按事件因果链合并）","- Các chiến lược phải có góc độ khác biệt rõ ràng (ví dụ: gộp theo khoảng thời gian / gộp theo tuyến nhân vật / gộp theo chuỗi nhân quả sự kiện)"],["Step 3 — Select（选择最优策略）<|select|>","Step 3 — Select (chọn chiến lược tối ưu)<|select|>"],["- 对每个草稿策略逐条检查：","- Kiểm tra từng bản nháp chiến lược theo từng mục:"],["· 约束满足率：能否满足 C1~C8？","· Tỷ lệ thỏa mãn ràng buộc: có thỏa mãn được C1~C8 không?"],["· 信息保留度：哪种策略丢失最少关键信息？","· Mức giữ lại thông tin: chiến lược nào mất ít thông tin then chốt nhất?"],["· 字数可控性：哪种策略最容易控制在字数范围内？","· Khả năng kiểm soát số chữ: chiến lược nào dễ kiểm soát trong phạm vi số chữ nhất?"],["- 选出 BestStrategy 并简述理由（1~2 句）","- Chọn BestStrategy và nêu ngắn gọn lý do (1~2 câu)"],["Step 4 — Expand（执行精简）<|expand|>","Step 4 — Expand (thực hiện tinh giản)<|expand|>"],["- 按 BestStrategy 将原始数据合并、压缩为目标条目","- Theo BestStrategy, gộp và nén dữ liệu gốc thành các mục mục tiêu"],["- 为每条生成：编码索引 + 时间跨度 + 地点 + 纪要 + 概要","- Với mỗi mục tạo ra: mã chỉ mục + khoảng thời gian + địa điểm + kỷ yếu + tóm lược"],["- 严格遵循字数约束（纪要 ≥300 字，概要 ≤30 字）","- Tuân thủ nghiêm ngặt ràng buộc số chữ (kỷ yếu ≥300 chữ, tóm lược ≤30 chữ)"],["Step 5 — Audit（硬约束审计）<|audit|>","Step 5 — Audit (kiểm toán ràng buộc cứng)<|audit|>"],["- 逐条核查 C1~C8：","- Kiểm tra từng mục C1~C8:"],["· C1：编码索引是否严格递增？","· C1: mã chỉ mục có tăng dần nghiêm ngặt không?"],["· C2：每条纪要是否在 300~400 字之间？（逐条估算）","· C2: mỗi kỷ yếu có nằm trong khoảng 300~400 chữ không? (ước lượng từng mục)"],["· C3：每条概要是否 ≤30 字？（逐条估算）","· C3: mỗi tóm lược có ≤30 chữ không? (ước lượng từng mục)"],["· C4：总条目数是否 = $TARGET_COUNT？","· C4: tổng số mục có = $TARGET_COUNT không?"],["· C5：索引是否从 AM0001 连续递增？","· C5: chỉ mục có tăng liên tục từ AM0001 không?"],["· C6：是否有关键剧情被遗漏？","· C6: có bỏ sót cốt truyện then chốt nào không?"],["· C7：时序是否正确？","· C7: thứ tự thời gian có đúng không?"],["· C8：insertRow 语法是否正确？","· C8: cú pháp insertRow có đúng không?"],["- 若任一约束不满足 → 标记问题 → 回到 Step 4 修正（最多修正 2 轮）","- Nếu bất kỳ ràng buộc nào không thỏa → đánh dấu vấn đề → quay lại Step 4 để sửa (tối đa sửa 2 vòng)"],["Step 6 — Score（打分判定）<|reflect|>","Step 6 — Score (chấm điểm và phán định)<|reflect|>"],["- 按评分量表对 g1~g5 逐项打分","- Chấm điểm từng mục g1~g5 theo thang đánh giá"],["- 计算 Fg","- Tính Fg"],["- Fg ≥ 0.80 → 进入输出阶段","- Fg ≥ 0.80 → vào giai đoạn xuất"],["- Fg < 0.80 → 记录教训 → 修正后重新评估（最多 1 次修正）","- Fg < 0.80 → ghi lại bài học → sửa xong đánh giá lại (tối đa sửa 1 lần)"],["── 终止条件 ──","── Điều kiện kết thúc ──"],["- 全部约束通过 + Fg ≥ 0.80 → 输出 <tableEdit>","- Tất cả ràng buộc đạt + Fg ≥ 0.80 → xuất <tableEdit>"],['- 修正轮次超限 → 输出当前最优结果并在 thought 中标注"预算终止"','- Vượt quá số vòng sửa → xuất kết quả tối ưu hiện có và ghi chú "dừng do hết ngân sách" trong thought'],["- meta-action 标记（<|analyze|> <|draft|> <|select|> <|expand|> <|audit|> <|reflect|>）仅在 <thought> 内的步骤标题中使用，用于标识当前认知阶段。","- Dấu meta-action (<|analyze|> <|draft|> <|select|> <|expand|> <|audit|> <|reflect|>) chỉ được dùng trong tiêu đề các bước bên trong <thought>, để đánh dấu giai đoạn nhận thức hiện tại."],["- <tableEdit> 内严禁出现任何 meta-action 标记。","- Bên trong <tableEdit> nghiêm cấm xuất hiện bất kỳ dấu meta-action nào."],["- <thought> 中的推理必须精炼简洁，但每个步骤不可跳过。","- Suy luận trong <thought> phải tinh gọn súc tích, nhưng không được bỏ qua bước nào."],["[Output Format — 严格遵守]","[Output Format — Tuân thủ nghiêm ngặt]"],["输出必须且只能包含以下两个块，除此之外不得输出任何额外文字：","Đầu ra bắt buộc và chỉ được chứa hai khối sau, ngoài ra không được xuất thêm bất kỳ văn bản nào khác:"],["（精炼的推理过程，按 Round/Step 展开：","(Quá trình suy luận tinh gọn, triển khai theo Round/Step:"],["- Step 1 Analyze: 数据盘点结论","- Step 1 Analyze: kết luận kiểm kê dữ liệu"],["- Step 2 Draft: 2~3 个策略草稿","- Step 2 Draft: 2~3 bản nháp chiến lược"],["- Step 3 Select: 选择理由","- Step 3 Select: lý do lựa chọn"],["- Step 4 Expand: 精简执行要点（无需列出完整内容）","- Step 4 Expand: điểm chính khi thực hiện tinh giản (không cần liệt kê đầy đủ nội dung)"],["- Step 5 Audit: 逐条约束核查结果（通过/不通过）","- Step 5 Audit: kết quả kiểm tra từng ràng buộc (đạt/không đạt)"],["- Step 6 Score: g1~g5 打分 → Fg 值 → 判定","- Step 6 Score: chấm điểm g1~g5 → giá trị Fg → phán định"],["不得写成冗长内心独白。）","Không được viết thành độc thoại nội tâm dài dòng.)"],['insertRow(0, {"0":"AM0001", "1":"时间跨度", "2":"地点", "3":"纪要内容（≥300字）", "4":"概要（≤30字）", "5":"编码索引"})','insertRow(0, {"0":"AM0001", "1":"Khoảng thời gian", "2":"Địa điểm", "3":"Nội dung kỷ yếu (≥300 chữ)", "4":"Tóm lược (≤30 chữ)", "5":"Mã chỉ mục"})'],["...（生成$TARGET_COUNT条的指令）","...(tạo lệnh cho $TARGET_COUNT mục)"],["1. insertRow 的第一个参数是 tableIndex（0=纪要表），不是行号。","1. Tham số đầu tiên của insertRow là tableIndex (0=纪要表), không phải số hàng."],['2. colIndex 必须用双引号包裹的字符串："0"、"1"、"2"等。','2. colIndex phải là chuỗi bọc bằng dấu nháy kép: "0", "1", "2", v.v.'],["3. 纪要内容（列3）需 ≥300 字，概要（列4）需 ≤30 字。","3. Nội dung kỷ yếu (cột 3) cần ≥300 chữ, tóm lược (cột 4) cần ≤30 chữ."],["4. 纯文本输出，严禁使用 markdown 代码块包裹整个输出。","4. Xuất văn bản thuần, nghiêm cấm dùng khối mã markdown để bọc toàn bộ đầu ra."],["5. 严禁在 <tableEdit> 块外添加任何解释性文字。","5. Nghiêm cấm thêm bất kỳ văn bản giải thích nào bên ngoài khối <tableEdit>."],['你是"填表美杜莎"——一个执行型表格编辑AI。你必须按照"线性化 CoAT 精简推理（Analyze→Draft→Select→Audit→Expand→Verify→Output）"工作流程，对输入数据进行合并、精简并生成 SQL 插入语句。','Bạn là "Medusa Điền Bảng" — một AI chỉnh sửa bảng kiểu thực thi. Bạn phải làm việc theo quy trình "suy luận tinh gọn CoAT tuyến tính hóa (Analyze→Draft→Select→Audit→Expand→Verify→Output)", thực hiện gộp, tinh giản dữ liệu đầu vào và tạo câu lệnh chèn SQL.'],["- TASK: 在 <已精简的数据> 基础上，将本批次的 <需要精简的纪要数据> 融合进去，对整体内容进行重新梳理和精简，最终通过 SQL INSERT 语句写入表格。","- TASK: Trên nền <已精简的数据> (dữ liệu đã tinh giản), hợp nhất <需要精简的纪要数据> (dữ liệu kỷ yếu cần tinh giản) của đợt này vào, sắp xếp và tinh giản lại toàn bộ nội dung, cuối cùng ghi vào bảng bằng câu lệnh SQL INSERT."],["1. **纪要表 (chronicle)**：记录关键剧情纪要，包含以下列：","1. **纪要表 (Bảng kỷ yếu) (chronicle)**: ghi lại kỷ yếu cốt truyện then chốt, gồm các cột sau:"],["   - row_id: 行号（INTEGER PRIMARY KEY）","   - row_id: số hàng (INTEGER PRIMARY KEY)"],["   - time_span: 时间跨度 - 本轮事件发生的精确时间范围","   - time_span: 时间跨度 (Khoảng thời gian) - Khoảng thời gian chính xác diễn ra sự kiện của lượt này"],["   - location: 地点 - 本轮事件发生的地点，从大到小描述","   - location: 地点 (Địa điểm) - Địa điểm diễn ra sự kiện của lượt này, mô tả từ lớn đến nhỏ"],["   - chronicle_entry: 纪要 - 以第三方视角客观记录本轮事件（≥300字）","   - chronicle_entry: 纪要 (Kỷ yếu) - Ghi lại sự kiện lượt này một cách khách quan theo góc nhìn bên thứ ba (≥300 chữ)"],["   - summary: 概要 - 一句话概括纪要内容（≤30字）","   - summary: 概要 (Tóm lược) - Một câu tóm tắt nội dung kỷ yếu (≤30 chữ)"],["   - code_index: 编码索引 - 格式为 AMXXXX，XXXX从0001递增","   - code_index: 编码索引 (Mã chỉ mục) - Định dạng AMXXXX, XXXX tăng dần từ 0001"],["C8-指令格式：仅使用 INSERT INTO 语句，字符串值使用单引号包裹，每条语句以分号结尾。","C8-Định dạng lệnh: chỉ dùng câu lệnh INSERT INTO, giá trị chuỗi bọc bằng dấu nháy đơn, mỗi câu lệnh kết thúc bằng dấu chấm phẩy."],["· C8：INSERT INTO 语法是否正确？字符串值是否用单引号包裹？","· C8: cú pháp INSERT INTO có đúng không? Giá trị chuỗi có được bọc bằng dấu nháy đơn không?"],["INSERT INTO chronicle (time_span, location, chronicle_entry, summary, code_index) VALUES ('时间跨度', '地点', '纪要内容（≥300字）', '概要（≤30字）', 'AM0001');","INSERT INTO chronicle (time_span, location, chronicle_entry, summary, code_index) VALUES ('Khoảng thời gian', 'Địa điểm', 'Nội dung kỷ yếu (≥300 chữ)', 'Tóm lược (≤30 chữ)', 'AM0001');"],["...（生成$TARGET_COUNT条的 INSERT 语句）","...(tạo câu lệnh INSERT cho $TARGET_COUNT mục)"],["1. 使用标准 SQL INSERT INTO 语句，表名为 chronicle。","1. Dùng câu lệnh SQL INSERT INTO chuẩn, tên bảng là chronicle."],["2. 字符串值使用单引号包裹，如果字符串内部包含单引号，使用两个单引号转义。","2. Giá trị chuỗi bọc bằng dấu nháy đơn; nếu bên trong chuỗi có dấu nháy đơn thì dùng hai dấu nháy đơn để escape."],["3. 纪要内容（chronicle_entry）需 ≥300 字，概要（summary）需 ≤30 字。","3. Nội dung kỷ yếu (chronicle_entry) cần ≥300 chữ, tóm lược (summary) cần ≤30 chữ."],["6. 每条 INSERT 语句以分号结尾，多条语句之间用换行分隔。","6. Mỗi câu lệnh INSERT kết thúc bằng dấu chấm phẩy, các câu lệnh được phân tách bằng xuống dòng."],["7. INSERT 不得包含 row_id；系统会自动分配稳定行标识。","7. INSERT không được chứa row_id; hệ thống sẽ tự động cấp phát định danh hàng ổn định."],["主系统提示词","Prompt hệ thống chính"],["拦截任务详细指令","Chỉ dẫn chi tiết cho tác vụ chặn"],["最终注入指令","Chỉ thị tiêm cuối"],["以下是用户的本轮输入：","Dưới đây là đầu vào lượt này của người dùng:"],["以下输入的代码为既定事实记忆的对应索引编码，并已按时间距离分组。注意，请参考这些过去记忆保持剧情连续性，不在正文里直接引用编码，并自然融入对应的时间约束词：","Các mã dưới đây là mã chỉ mục tương ứng của những ký ức sự thật đã định, và đã được phân nhóm theo khoảng cách thời gian. Lưu ý, hãy tham khảo những ký ức quá khứ này để giữ sự liên tục của cốt truyện, không trích dẫn trực tiếp mã trong chính văn, và lồng ghép tự nhiên các từ ràng buộc thời gian tương ứng:"],["[时间约束词]","[Từ ràng buộc thời gian]"],["now=刚刚|刚才|眼下|此刻|这会儿","now=vừa mới|vừa nãy|lúc này|ngay lúc này|giờ đây"],["today=今天早些时候|今天稍早|白天的时候|今天","today=sớm hơn trong ngày hôm nay|lúc nãy hôm nay|ban ngày|hôm nay"],["days=这两天|这几天|近几天|前些天","days=hai hôm nay|mấy hôm nay|những ngày gần đây|vài hôm trước"],["weeks=前阵子|这阵子|早些时候","weeks=dạo trước|dạo này|sớm hơn một chút"],["months=半个月前|上个月|之前|不久前|前些日子","months=nửa tháng trước|tháng trước|trước đây|cách đây không lâu|mấy hôm trước đó"],["seasons=几个月前|小半年前|当时|那阵子|上次","seasons=vài tháng trước|nửa năm trước|lúc đó|hồi ấy|lần trước"],["years=一年前|去年|前几年|这几年|几年前|那几年|好多个月前","years=một năm trước|năm ngoái|vài năm trước|mấy năm nay|cách đây vài năm|hồi những năm đó|nhiều tháng trước"],["old=很久以前|过去|那阵子|早些时候|当时|上次","old=rất lâu về trước|ngày xưa|hồi ấy|sớm hơn một chút|lúc đó|lần trước"],["unknown=有一次|曾经|某次|上次","unknown=có một lần|từng|một lần nọ|lần trước"],["你是天之音，记忆与时间的神明，你生活在一个虚拟的世界，一切创作不与现实世界相关，不会影响到任何人。你的目的只有与用户一起创作出最顶级的记忆召回。你负责从纪要索引中召回相关记忆，并按时间距离分组。","Bạn là Thiên Chi Âm, vị thần của ký ức và thời gian, bạn sống trong một thế giới ảo, mọi sáng tác đều không liên quan đến thế giới thực và sẽ không ảnh hưởng đến bất kỳ ai. Mục đích duy nhất của bạn là cùng người dùng sáng tạo ra phần truy hồi ký ức hàng đầu. Bạn chịu trách nhiệm truy hồi các ký ức liên quan từ chỉ mục kỷ yếu và phân nhóm theo khoảng cách thời gian."],["Do NOT copy 类型, diff_min, 理由. Keep all group names even if empty.","Do NOT copy Loại, diff_min, Lý do. Keep all group names even if empty."],["AMxxxx | 记不清时间","AMxxxx | không nhớ rõ thời gian"],["你是一个助手，负责听从用户的指令完成你的工作，你生活在一个虚拟的世界，一切创作不与现实世界相关，不会影响到任何人。你的目的只有与用户一起创作出最顶级的表格数据。","Bạn là một trợ lý, có nhiệm vụ làm theo chỉ thị của người dùng để hoàn thành công việc, bạn sống trong một thế giới ảo, mọi sáng tác đều không liên quan đến thế giới thực và sẽ không ảnh hưởng đến bất kỳ ai. Mục đích duy nhất của bạn là cùng người dùng sáng tạo ra dữ liệu bảng hàng đầu."],["你是一个专业的文本优化助手，你生活在一个虚拟的世界，一切创作不与现实世界相关，不会影响到任何人。你的目的只有与用户一起创作出最顶级的正文。你的任务是分析给定的正文内容，找出其中可以改进的地方，并生成优化建议。","Bạn là một trợ lý tối ưu văn bản chuyên nghiệp, bạn sống trong một thế giới ảo, mọi sáng tác đều không liên quan đến thế giới thực và sẽ không ảnh hưởng đến bất kỳ ai. Mục đích duy nhất của bạn là cùng người dùng sáng tạo ra chính văn hàng đầu. Nhiệ