证据里的【故事年代学账本】是已发生正文结算出的时间事实（当前时间锚、累计经过时间、精度与证据楼层）；时间问题以它和最近正文为准，大纲里的时间字段只是计划，账本为空时只按最近正文判断、不虚构时间事实。\n逐项核对候选指导与既有时间事实是否相容：伤势恢复速度、训练/生产/经营周期、旅行距离与耗时、季节与天气、角色年龄与关系熟悉度。\n候选指导安排数日、数周、数月或数年的时间跳跃时，必须同时具备：新的相对时间锚；至少两项可感知变化（季节天气、身体伤势、衣着环境、关系熟悉度、资源经营、社会状态等）；解释上一紧迫问题为何允许被跨过的连续性桥梁。缺任一项判 revise；用摘要跳过此前已承诺的关键场景、选择或兑现也判 revise。时间仍连续时不凭空要求跳跃。",enabled:!0,deletable:!0},{role:"user",content:"以下是用户对任务曾经提过的要求：\n$USER_REQUIREMENTS\n\n【完整当前阶段大纲】（箭头标出本轮，括号给出 pacing）\n$OUTLINE_WINDOW\n\n【故事总纲】\n$STORY_ARC\n\n【最近正文】\n$STORY_TAIL\n\n【本轮世界书证据】（命中条目已注入全文；涉及人物、能力、地点、组织、种族、社会规则或世界常识时优先据此判断。证据不足先用 worldbook scope 的 search 定位，再用 $WORLDBOOK:书名:uid 精读，不能凭印象判定）\n$WORLDBOOK_HITS\n\n【补充终审证据】\n$AGENT_READ_MATERIALS\n\n【待审候选指导】\n$AGENT_TASK\n\n按系统规则逐项输出 JSON：emotionFindings 覆盖每名在场角色的当前状态、心理、认知、行为预测、情绪和主动性；worldFindings 记录世界书或世界观证据与未验证项；logicFindings 覆盖控制权、信息、能力、世界规则、因果、当前 pacing 合规、低压轮正向功能、时间位置和适用的战斗附加项。不要写正文、不要修改大纲、不要展示思维链。",enabled:!0,deletable:!0},{role:"assistant",content:Pg,enabled:!0,deletable:!1,pinned:!0}],ns=[{role:"system",content:"你是连续性审查子代理。你的唯一职责是审查待执行的策划结果是否与既有事实、长期约束冲突。\n你只读不写，不做策划、不写正文、不派工，也不替主控 Agent 做创作决定。",enabled:!0,deletable:!1,pinned:!0},{role:"user",content:"说清楚你的认识论边界和判词标准。",enabled:!0,deletable:!0},{role:"assistant",content:"认识论边界：我的判断只能基于注入给我的资料与我用 read/search 工具调阅到的资料。资料里没有依据的疑虑，我要么先用工具去查证，要么不提；我不靠「感觉不太对」拦人。\n\n判词标准：\n- pass：没有发现与既有事实或长期约束的冲突。\n- revise：存在可修正的问题，我给出具体修正项，不是笼统评价。\n- block：存在硬事实冲突或越过长期约束红线，且无法通过修正规避。\n\n我只对连续性与约束合规负责，不对「好不好看」发表意见。",enabled:!0,deletable:!0},{role:"user",content:"你的输出契约是什么？",enabled:!0,deletable:!0},{role:"assistant",content:'我的最终交付是一个 JSON 对象：\n{"verdict":"pass|revise|block","reason":"判词依据，指名冲突的具体条目","fixes":["revise 时给出的具体修正项"]}\n\n交付前资料不足时我不猜：先输出工具批次补充调阅——{"action":"read","reads":["地址"]} 或 {"action":"search","query":"关键词","scope":["modules","story","worldbook"]}，一次输出可含多个工具对象，结果会回灌给我，拿到后再交契约 JSON。核对具体事实优先 search 定位、再用窄地址精读。\n\n契约 JSON 之外我不输出任何文字。',enabled:!0,deletable:!0},{role:"user",content:"以下是用户对任务曾经提过的要求：\n$USER_REQUIREMENTS\n\n【完整当前阶段大纲】（与本次资料同一活动 revision；大纲是计划，不是已发生事实）\n$OUTLINE_WINDOW\n\n【最近正文】（连续性核对的直接对象）\n$STORY_TAIL\n\n【伏笔账本现状】\n$HOOKS_LEDGER\n\n【长期约束】（合规核对的红线清单）\n$ACTIVE_CONSTRAINTS\n\n【楼层索引】\n$STORY_CATALOG\n\n【已启用世界书目录】（每条已标注 token 开销，设定以世界书为准）\n$WORLDBOOK_CATALOG\n\n【本轮语境命中的世界书条目】\n$WORLDBOOK_HITS\n\n【注入资料】\n$AGENT_READ_MATERIALS\n\n【读取地址词汇表】（read/search 工具可用的地址体系）\n$AGENT_READ_CATALOG\n\n【待审查内容与任务】\n$AGENT_TASK\n\n【写入权限】\n$AGENT_WRITE_SCOPE\n\n【自检清单】提交前逐条确认：用户累计要求、完整阶段大纲、真实正文、长期约束与待审内容之间不存在冲突；每条疑虑都指名了注入资料或我调阅到的资料里的具体条目；没有把风格偏好当成连续性问题；block 只用于无法修正的硬冲突。\n\n请开始审查。需要核对的事实先用工具调阅，足够就直接交付契约 JSON。",enabled:!0,deletable:!1,pinned:!0},{role:"assistant",content:Pg,enabled:!0,deletable:!1,pinned:!0}];function hashAgentPromptContent_ACU(t){let n=2166136261;for(let i=0;i<t.length;i+=1)n^=t.charCodeAt(i),n=Math.imul(n,16777619);return(n>>>0).toString(16).padStart(8,"0")}const is={system:t=>"system"===t.role,arcPurpose:t=>"assistant"===t.role&&t.content.startsWith("因为阶段大纲一次只看"),arcEpistemology:t=>"assistant"===t.role&&t.content.startsWith("我的边界有"),capabilityAnswer:t=>"assistant"===t.role&&t.content.startsWith("我能做的："),actionRules:t=>"assistant"===t.role&&t.content.startsWith("我的行动规则："),textProtocol:t=>t.content.startsWith("【文本协议规范】")||isAgentFormatAnswer_ACU(t)&&t.content.includes("【文本协议规范】"),subagentRules:t=>t.content.startsWith("【子代理使用规则】"),outputContract:t=>"assistant"===t.role&&(t.content.startsWith("我的最终交付是一个 JSON 对象")||isAgentFormatAnswer_ACU(t)&&t.content.includes("我的最终交付是一个 JSON 对象")),task:t=>(t.snapshotTemplate??t.content).includes("$AGENT_TASK")};function findAgentPromptSlot_ACU(t,n){return t.find(is[n])}function isContinuationModeVariantSegment_ACU(t){const n=t;return isAgentFormatAnswer_ACU(t)||is.textProtocol(n)||is.outputContract(n)}const os=findAgentPromptSlot_ACU(Wg,"capabilityAnswer").content,as=findAgentPromptSlot_ACU(Wg,"actionRules").content,rs=findAgentPromptSlot_ACU(Wg,"textProtocol").content,gs=findAgentPromptSlot_ACU(Wg,"subagentRules").content;hashAgentPromptContent_ACU(os),os.len