ừng ghi các cột cấp tập. volume ngoài các cột bắt buộc của story còn phải ghi narrative_role, target_stage_range, target_time_span, progress_ceiling, sustaining_threads, payoff_targets. Cùng một lúc chỉ được có một volume có status là active, các tập còn lại là planned.","Khi nào dùng: chưa có tổng cương thì INSERT toàn truyện và các tập; sau khi giai đoạn hoàn thành chỉ UPDATE stage_numbers của tập hiện tại; khi tập khép lại thì UPDATE status và căn cứ hoàn thành; bỏ một tập thì dùng DELETE và ghi reason.","Ví dụ (toàn truyện cộng tập một, hàng mới có số hiệu chỉnh là 0):","INSERT INTO story_arc (scope, title, direction, escalation, withheld, status) VALUES ('story', 'Truy tìm sự thật', 'Nhân vật chính phải làm rõ lai lịch cấm địa, thất bại sẽ mất tư cách vào thành', 'Từ nghi ngờ ngoài cổng đến xác nhận người gác cổng biết chuyện', 'Thân phận cuối cùng', 'active');","INSERT INTO story_arc (scope, title, direction, escalation, withheld, status, narrative_role, target_stage_range, target_time_span, progress_ceiling, sustaining_threads, payoff_targets) VALUES ('volume', 'Vào thành', 'Nhân vật chính chọn vào thành và làm quen người gác cổng', 'Từ quan sát ngoài cổng đến lấy được manh mối đầu tiên', 'Thân phận thật của người gác cổng', 'active', 'setup', '{\"min\":1,\"max\":2}', 'vài ngày', 'Chỉ xác nhận lối vào, không vén lõi cấm địa', '[\"Lòng tin với người gác cổng\"]', '[\"Lấy được manh mối mảnh tinh thể đầu tiên\"]');","Sửa tập đã có (7 chỉ là minh họa, thay bằng giá trị hiện tại của revisions.storyArc): UPDATE story_arc SET stage_numbers = '[1]' WHERE id = 'VOL-01' AND expected_revision = 7;","Xóa: DELETE FROM story_arc WHERE id = 'VOL-02' AND reason = 'Mâu thuẫn với chính văn' AND expected_revision = 7;"].join("\n"):"hook-cognition-maintainer"===t?[...i,"Chỉ ghi hooks, info_gap, chronology và constraint_proposals đề xuất đăng ký. Chỉ đăng ký những thay đổi đã thực sự xảy ra trong chính văn. Trường thời gian trong dàn ý là kế hoạch, không được ghi vào chronology.","Khi nào dùng: gọi khi chính văn mới xuất hiện manh mối, phục bút bị chạm lại, nhân vật biết thêm điều gì, hoặc chính văn thực sự qua đêm/qua ngày. Không có thay đổi có thể chứng thực thì đừng gọi.","Ví dụ phục bút: INSERT INTO hooks (summary, status, importance, planted_index, planned_payoff) VALUES ('Người gác cổng giấu mảnh tinh thể trong tay phải', 'planted', 'mid', 3, 'Sau khi vào thành, người gác cổng tự tay giao ra');","status chỉ được là planted, reinforced, misled, partially_paid, paid, abandoned. importance chỉ được là high, mid, low.","Ví dụ chênh lệch thông tin: INSERT INTO info_gap (topic, objective_fact, reader_known, character_knowledge, reveal_status) VALUES ('Lai lịch mảnh tinh thể', 'Mảnh tinh thể đến từ lõi cấm địa', 'Độc giả chỉ thấy người gác cổng giấu mảnh tinh thể', '[{\"name\":\"Người gác cổng\",\"knows\":\"Tự tay giữ mảnh tinh thể\"}]', 'partial');","Khi reveal_status là revealed thì phải ghi đồng thời reveal_index; chưa tiết lộ thì reveal_index ghi NULL. Nội dung nhân vật biết phải truy được về tự trải qua, tận mắt thấy, nghe nói, đọc được hoặc được kể lại.","Ví dụ niên đại học: INSERT INTO chronology (anchor, elapsed, precision, transition, evidence_indexes) VALUES ('Sáng sớm ngày thứ hai sau khi vào thành', 'Khoảng hai ngày kể từ mở đầu', 'approximate', 'Canh ở cổng thành suốt một đêm', '[3,4]');","precision chỉ được là exact, approximate, unknown. evidence_indexes phải là số tầng chính văn AI đã xuất hiện, có thể trích dẫn tầng đang quyết toán lần này; tầng của người dùng và tầng không tồn tại sẽ bị từ chối.","Đề xuất ràng buộc: chỉ đăng ký đề xuất khi chính văn thật sự bộc lộ ranh giới mới cần tuân thủ lâu dài; việc này không trực tiếp sửa ràng buộc dài hạn, phải do Agent chính quyết định. constraint_proposals chỉ được INSERT, chỉ có một cột text, không ghi id, UPDATE hay DELETE. Ví dụ: INSERT INTO constraint_proposals (text) VALUES ('Trước khi thu hồi phục bút, đừng tiết lộ sớm thân phận người gác cổng');","Sửa phục bút đã có (7 chỉ l